mapper.select:
SELECT DISTINCT
bi.* FROM bbx_invitation bi
LEFT JOIN bbx_invitation_visitor biv ON biv.invite_id = bi.id
LEFT JOIN bbx_invitation_space_relation bisr ON bisr.invite_id = bi.id


        AND bi.tenant_id = #{condition.tenantId}


        AND biv.name like concat('%',#{condition.visitorName},'%')


        AND bisr.space_id = #{condition.spaceId}


        AND (#{condition.createTimeStart} <= bi.create_time and #{condition.createTimeEnd} >= bi.create_time)


        AND bi.invite_uname like concat('%',#{condition.inviteUname},'%')


        AND bi.invite_uid =#{condition.inviteUid}


        AND bi.receive_uname like concat('%',#{condition.receiveUname},'%')


        AND bi.receive_uid =#{condition.receiveUid}


        AND bi.invite_status =#{condition.inviteStatus}


        AND bi.visit_reason_type =#{condition.visitReasonType}


ORDER BY bi.invite_status asc, bi.start_time asc

SELECT DISTINCT bi.* FROM bbx_invitation bi
LEFT JOIN bbx_invitation_visitor biv ON biv.invite_id = bi.id
LEFT JOIN bbx_invitation_space_relation bisr ON bisr.invite_id = bi.id


        AND bi.tenant_id = #{condition.tenantId}


        AND biv.name like concat('%',#{condition.visitorName},'%')


        AND bisr.space_id = #{condition.spaceId}


        AND (#{condition.createTimeStart} <= bi.create_time and #{condition.createTimeEnd} >= bi.create_time)


        AND bi.invite_uname like concat('%',#{condition.inviteUname},'%')


        AND bi.invite_uid =#{condition.inviteUid}


        AND bi.receive_uname like concat('%',#{condition.receiveUname},'%')


        AND bi.receive_uid =#{condition.receiveUid}


        AND bi.invite_status =#{condition.inviteStatus}


        AND bi.visit_reason_type =#{condition.visitReasonType}


ORDER BY bi.create_time desc

SELECT DISTINCT bi.* FROM bbx_invitation bi LEFT JOIN bbx_task_assignment bta ON bta.business_id = bi.id
AND bi.tenant_id =#{condition.tenantId}
AND bta.user_id =#{condition.userId}
ORDER BY bi.create_time desc
